-- Permanent Student ID: generated by PostgreSQL from a sequence (concurrency-safe,
-- never derived from row counts). Gaps from rolled-back transactions are acceptable.
CREATE SEQUENCE student_id_seq AS BIGINT START 1 MINVALUE 1 MAXVALUE 99999999 NO CYCLE;

CREATE TABLE student_profiles (
    id            BIGSERIAL PRIMARY KEY,
    user_id       BIGINT NOT NULL UNIQUE REFERENCES users(id),
    student_id    TEXT NOT NULL UNIQUE
                  DEFAULT ('IHA-PK-' || lpad(nextval('student_id_seq')::text, 8, '0'))
                  CONSTRAINT student_id_format CHECK (student_id ~ '^IHA-PK-[0-9]{8}$'),
    registration_date DATE NOT NULL DEFAULT CURRENT_DATE,

    full_name        TEXT,
    father_name      TEXT,
    mother_name      TEXT,
    gender           TEXT CHECK (gender IN ('male', 'female', 'other')),
    date_of_birth    DATE CHECK (date_of_birth >= DATE '1900-01-01'),
    nationality      TEXT,
    id_number        TEXT CHECK (id_number IS NULL OR id_number ~ '^[0-9]{5}-?[0-9]{7}-?[0-9]$'),  -- CNIC / B-Form
    contact_number   TEXT,
    photo_path       TEXT,

    -- current residence
    address_line     TEXT,
    province_id      INTEGER REFERENCES provinces(id),
    district_id      INTEGER,
    city_id          INTEGER,
    city_other       TEXT,
    postal_code      TEXT,

    -- permanent address
    perm_same_as_current BOOLEAN NOT NULL DEFAULT FALSE,
    perm_address_line    TEXT,
    perm_province_id     INTEGER REFERENCES provinces(id),
    perm_district_id     INTEGER,
    perm_city_id         INTEGER,
    perm_city_other      TEXT,
    perm_postal_code     TEXT,

    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT now(),

    -- Geography integrity enforced by the database itself: the district must belong to the
    -- province, and the city to the district. NULL columns skip the composite FK (MATCH SIMPLE),
    -- so the chain checks below stop a child being set without its parent.
    CONSTRAINT sp_district_fk FOREIGN KEY (district_id, province_id) REFERENCES districts (id, province_id),
    CONSTRAINT sp_city_fk     FOREIGN KEY (city_id, district_id)     REFERENCES cities (id, district_id),
    CONSTRAINT sp_geo_chain   CHECK ((district_id IS NULL OR province_id IS NOT NULL)
                                 AND (city_id IS NULL OR district_id IS NOT NULL)
                                 AND (city_other IS NULL OR district_id IS NOT NULL)),
    CONSTRAINT sp_city_xor    CHECK (city_id IS NULL OR city_other IS NULL),
    CONSTRAINT sp_city_other_len CHECK (city_other IS NULL OR length(btrim(city_other)) BETWEEN 2 AND 100),

    CONSTRAINT sp_perm_district_fk FOREIGN KEY (perm_district_id, perm_province_id) REFERENCES districts (id, province_id),
    CONSTRAINT sp_perm_city_fk     FOREIGN KEY (perm_city_id, perm_district_id)     REFERENCES cities (id, district_id),
    CONSTRAINT sp_perm_geo_chain   CHECK ((perm_district_id IS NULL OR perm_province_id IS NOT NULL)
                                      AND (perm_city_id IS NULL OR perm_district_id IS NOT NULL)
                                      AND (perm_city_other IS NULL OR perm_district_id IS NOT NULL)),
    CONSTRAINT sp_perm_city_xor    CHECK (perm_city_id IS NULL OR perm_city_other IS NULL),
    CONSTRAINT sp_perm_city_other_len CHECK (perm_city_other IS NULL OR length(btrim(perm_city_other)) BETWEEN 2 AND 100)
);

CREATE INDEX sp_name_idx     ON student_profiles (lower(full_name));
CREATE INDEX sp_location_idx ON student_profiles (province_id, district_id, city_id);
CREATE TRIGGER sp_updated BEFORE UPDATE ON student_profiles FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- Student ID and owning user can never change after creation.
CREATE FUNCTION student_profiles_lock_identity() RETURNS trigger AS $$
BEGIN
    IF NEW.student_id IS DISTINCT FROM OLD.student_id THEN
        RAISE EXCEPTION 'student_id is permanent and cannot be changed';
    END IF;
    IF NEW.user_id IS DISTINCT FROM OLD.user_id THEN
        RAISE EXCEPTION 'student profile cannot be reassigned to another user';
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER sp_lock_identity BEFORE UPDATE ON student_profiles
    FOR EACH ROW EXECUTE FUNCTION student_profiles_lock_identity();
